import java.util.Collections;
import java.util.List;

class Solution {
    public int maxIncreasingGroups(List<Integer> usageLimits) {
        Collections.sort(usageLimits);
        int ans = 1;
        long available = 0;
        for (int limit : usageLimits) {
            available += limit;
            if (available >= (long) ans * (ans + 1) / 2) {
                ans++;
            }
        }
        return ans - 1;
    }
}

/**
 * @param {number[]} usageLimits
 * @return {number}
 */
var maxIncreasingGroups = function(usageLimits) {
    usageLimits.sort((a, b) => a - b);
    let ans = 1;
    let available = 0;
    for (const limit of usageLimits) {
        available += limit;
        if (available >= (ans * (ans + 1)) / 2) {
            ans++;
        }
    }
    return ans - 1;
};
